CREATE TYPE "SourceType" AS ENUM ('M3U', 'XTREAM', 'PORTAL_MAC', 'DIRECT');
CREATE TYPE "SourceStatus" AS ENUM ('DRAFT', 'TESTING', 'READY', 'SYNCING', 'DEGRADED', 'AUTH_FAILED', 'EXPIRED', 'OFFLINE', 'DISABLED');
CREATE TYPE "SourceTestOutcome" AS ENUM ('SUCCESS', 'AUTH_FAILED', 'EXPIRED', 'UNREACHABLE', 'INVALID_FORMAT', 'BLOCKED', 'UNSUPPORTED');
CREATE TABLE "SourceAccount" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "type" "SourceType" NOT NULL, "status" "SourceStatus" NOT NULL DEFAULT 'DRAFT', "baseUrl" TEXT NOT NULL, "regionCode" TEXT, "priority" INTEGER NOT NULL DEFAULT 100, "enabled" BOOLEAN NOT NULL DEFAULT false, "syncLive" BOOLEAN NOT NULL DEFAULT true, "syncMovies" BOOLEAN NOT NULL DEFAULT true, "syncSeries" BOOLEAN NOT NULL DEFAULT true, "syncEpg" BOOLEAN NOT NULL DEFAULT false, "userAgent" TEXT, "epgUrl" TEXT, "refreshIntervalMin" INTEGER NOT NULL DEFAULT 360, "maxConcurrentStreams" INTEGER, "preferHls" BOOLEAN NOT NULL DEFAULT true, "allowedHosts" TEXT[] NOT NULL, "ownerId" TEXT NOT NULL, "lastTestedAt" TIMESTAMP(3), "lastSuccessAt" TIMESTAMP(3), "lastErrorCode" TEXT, "lastLatencyMs" INTEGER, "accountExpiresAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SourceAccount_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SourceSecret" ("sourceId" TEXT NOT NULL, "ciphertext" TEXT NOT NULL, "iv" TEXT NOT NULL, "authTag" TEXT NOT NULL, "keyVersion" INTEGER NOT NULL DEFAULT 1, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SourceSecret_pkey" PRIMARY KEY ("sourceId"));
CREATE TABLE "SourceTestRun" ("id" TEXT NOT NULL, "sourceId" TEXT NOT NULL, "outcome" "SourceTestOutcome" NOT NULL, "latencyMs" INTEGER, "capabilities" JSONB, "errorCode" TEXT, "detail" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SourceTestRun_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SourceAuditEvent" ("id" TEXT NOT NULL, "sourceId" TEXT NOT NULL, "actorId" TEXT NOT NULL, "action" TEXT NOT NULL, "changes" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SourceAuditEvent_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SourceAccount_type_status_enabled_idx" ON "SourceAccount"("type", "status", "enabled"); CREATE INDEX "SourceAccount_ownerId_updatedAt_idx" ON "SourceAccount"("ownerId", "updatedAt"); CREATE INDEX "SourceTestRun_sourceId_createdAt_idx" ON "SourceTestRun"("sourceId", "createdAt"); CREATE INDEX "SourceAuditEvent_sourceId_createdAt_idx" ON "SourceAuditEvent"("sourceId", "createdAt"); CREATE INDEX "SourceAuditEvent_actorId_createdAt_idx" ON "SourceAuditEvent"("actorId", "createdAt");
ALTER TABLE "SourceAccount" ADD CONSTRAINT "SourceAccount_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SourceSecret" ADD CONSTRAINT "SourceSecret_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "SourceAccount"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SourceTestRun" ADD CONSTRAINT "SourceTestRun_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "SourceAccount"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SourceAuditEvent" ADD CONSTRAINT "SourceAuditEvent_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "SourceAccount"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SourceAuditEvent" ADD CONSTRAINT "SourceAuditEvent_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
